/bin/bash -lc "PYTHONPATH=lib python - <<'PY'
from ansible.utils.encrypt import CryptHash
for ident in ('2', '2a', '2y', '2b'):
    try:
        print(ident, CryptHash('bcrypt').hash('123', salt='1234567890123456789012', ident=ident))
    except Exception as exc:
        print(ident, type(exc).__name__, str(exc))
PY"

